package com.example.admin.core.model

data class AdminUser(val id: String, val name: String, val email: String, val role: String, val clearanceLevel: String, val avatarInitials: String = "EV")
data class IncidentRecord(val id: String, val title: String, val region: String, val severity: String, val casualtiesReported: Int, val teamsDeployed: Int, val status: String, val timestamp: String)
data class VolunteerRecord(val id: String, val name: String, val email: String, val phone: String, val location: String, val status: String, val rating: Double, val deploymentsCount: Int, val skills: List<String>, val availability: String = "Immediate", val emergencyContact: String = "Not provided", val certifications: List<String> = emptyList(), val recentAssignment: String = "No assignment")
data class MissionDispatch(val id: String, val title: String, val description: String, val status: String, val priority: String, val location: String, val volunteersAssigned: Int, val requiredVolunteers: Int, val startTime: String, val estimatedDuration: String, val skillsRequired: List<String>, val coordinator: String)
data class DeploymentAssignment(val id: String, val volunteerId: String, val missionId: String, val role: String, val notes: String, val active: Boolean = true)
data class TacticalUnit(val id: String, val name: String, val unitType: String, val personnelCount: Int, val latNormalized: Float, val lngNormalized: Float, val status: String, val assignedIncident: String)
data class ResourceItem(val id: String, val name: String, val available: Int, val total: Int, val unit: String)
data class SkillItem(val id: String, val name: String, val category: String, val volunteerCount: Int, val availableCount: Int, val demand: String, val rating: Double, val description: String)
data class SkillCategory(val id: String, val name: String, val count: Int)
data class EmergencyAlert(val id: String, val title: String, val message: String, val timestamp: String, val priority: String, val channel: String, val recipientsCount: Int, val responsesCount: Int, val sender: String = "Elena Vance", val targetAudience: String = "All volunteers", val recipientIds: List<String> = emptyList(), val deliveryStatus: String = "Saved locally")
data class SecurityEvent(val id: String, val type: String, val severity: String, val message: String, val timestamp: String, val status: String, val ipAddress: String = "Local device")
data class AccessControlRule(val id: String, val name: String, val isEnabled: Boolean, val coverage: String, val description: String)
data class ComplianceRecord(val id: String, val standard: String, val status: String, val lastAudit: String, val certBody: String)
data class AnalyticsKPI(val title: String, val value: String, val change: String, val isPositive: Boolean, val subtitle: String)
data class DeploymentTrend(val month: String, val volunteers: Int, val missions: Int, val responseTimeHours: Float)
data class MissionDistribution(val type: String, val count: Int, val percentage: Int)
data class RegionalEfficiency(val region: String, val volunteers: Int, val missions: Int, val efficiencyScore: Int)
data class AnalyticsMessage(val id: String, val isFromUser: Boolean, val text: String, val timestamp: String)
data class AdminSettings(val organizationName: String = "VolunteerOps Response Network", val timezone: String = "Africa/Nairobi", val language: String = "English", val emailAlerts: Boolean = true, val smsAlerts: Boolean = false, val pushAlerts: Boolean = true, val emergencyBroadcastAutoForward: Boolean = false, val twoFactorAuth: Boolean = true, val sessionTimeoutMinutes: Int = 30, val apiAccessEnabled: Boolean = false, val webhooksEnabled: Boolean = false)
data class HelpArticle(val id: String, val title: String, val category: String, val format: String, val readTime: String, val popularity: String, val summary: String, val steps: List<String> = emptyList())
data class MutationResult(val success: Boolean, val message: String)
